-- ViewRepository.getFolderSummary
with
  "scoped" as (
    select
      "id",
      "fileCreatedAt",
      case
        when strpos(substr("originalPath", length($1::text) + 1), '/') > 0 then split_part(
          substr("originalPath", length($2::text) + 1),
          '/',
          1
        )
      end as "name"
    from
      "asset"
    where
      "ownerId" = $3::uuid
      and "originalPath" like $4
      and "visibility" = $5
      and "deletedAt" is null
      and "fileCreatedAt" is not null
      and "fileModifiedAt" is not null
      and "localDateTime" is not null
  ),
  "counts" as (
    select
      "name",
      count(*)::int as "assetCount"
    from
      "scoped"
    group by
      "name"
  ),
  "covers" as (
    select distinct
      on ("name") "name",
      "id" as "coverAssetId"
    from
      "scoped"
    where
      "name" is not null
    order by
      "name",
      "fileCreatedAt" desc,
      "id"
  )
select
  "counts"."name",
  "counts"."assetCount",
  "covers"."coverAssetId"
from
  "counts"
  left join "covers" on "covers"."name" = "counts"."name"
order by
  "counts"."name" asc nulls first

